"""Core epidemic-curve logic: binning, zero-filling, ASCII rendering."""

from __future__ import annotations

from datetime import date, timedelta
from typing import Iterable, Mapping


def _parse_onset(value) -> date:
    if isinstance(value, date):
        return value
    return date.fromisoformat(value)


def _week_key(d: date) -> str:
    """ISO-8601 week label, e.g. '2025-W01'."""
    iso_year, iso_week, _ = d.isocalendar()
    return f"{iso_year:04d}-W{iso_week:02d}"


def _week_monday(d: date) -> date:
    """Monday of the ISO week containing d."""
    iso_year, iso_week, _ = d.isocalendar()
    # ISO week 1 Monday: back up from Jan 4 (always in ISO week 1).
    jan4 = date(iso_year, 1, 4)
    week1_monday = jan4 - timedelta(days=jan4.isoweekday() - 1)
    return week1_monday + timedelta(weeks=iso_week - 1)


def epicurve(cases: Iterable[dict], bin: str = "day") -> dict:
    """Count case onsets per time bin.

    bin="day"  -> one bin per calendar date, keyed "YYYY-MM-DD".
    bin="week" -> one bin per ISO-8601 week, keyed "YYYY-Www".
    Empty bins between the earliest and latest onset are filled with zeros.
    """
    if bin not in ("day", "week"):
        raise ValueError(f"bin must be 'day' or 'week', got {bin!r}")

    counts: dict = {}
    for c in cases:
        onset = _parse_onset(c["onset"])
        key = onset.isoformat() if bin == "day" else _week_key(onset)
        counts[key] = counts.get(key, 0) + 1

    if not counts:
        return {}

    if bin == "day":
        first = date.fromisoformat(min(counts))
        last = date.fromisoformat(max(counts))
        cur = first
        while cur <= last:
            counts.setdefault(cur.isoformat(), 0)
            cur += timedelta(days=1)
    else:
        first_monday = _week_monday(date.fromisoformat(min(counts)))
        last_monday = _week_monday(date.fromisoformat(max(counts)))
        cur = first_monday
        while cur <= last_monday:
            counts.setdefault(_week_key(cur), 0)
            cur += timedelta(weeks=1)

    return dict(sorted(counts.items()))


def render(counts: Mapping[str, int], width: int = 40) -> str:
    """Render counts as an ASCII bar chart.

    One line per bin: '<bin> <bar> <count>', bars scaled so the max count
    spans `width` characters. Returns text with a trailing newline.
    """
    if not counts:
        return ""
    peak = max(counts.values())
    lines = []
    for label, count in counts.items():
        bar_len = round(count * width / peak)
        lines.append(f"{label} {'#' * bar_len} {count}")
    return "\n".join(lines) + "\n"

